Here's how to handle each scenario with modern MSTest (3.9+/3.10+):

```csharp
[TestClass]
public sealed class MyTests
{
    private readonly TestContext _testContext;
    private string? _tempFile;

    public MyTests(TestContext testContext)
    {
        _testContext = testContext;
    }

    // 1. Windows-only (skipped on Linux/macOS)
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void Registry_ReadsExpectedValue()
    {
        var value = Registry.GetValue(@"HKEY_LOCAL_MACHINE\SOFTWARE\...", "Key", null);
        Assert.IsNotNull(value);
    }

    // 2. Skip in CI (requires local GPU)
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    public void GpuRendering_ProducesExpectedOutput()
    {
        var result = GpuRenderer.Render(scene);
        Assert.IsNotNull(result);
    }

    // 3. Flaky external API — retry up to 3 times
    [TestMethod]
    [Retry(3)]
    [Timeout(10000)]
    public async Task WeatherApi_ReturnsForecast()
    {
        var forecast = await _weatherClient.GetForecastAsync(
            _testContext.CancellationToken);
        Assert.IsNotNull(forecast);
    }

    // 4. Temp file cleanup — TestCleanup runs even on failure
    [TestMethod]
    public void Export_WritesToFile()
    {
        _tempFile = Path.GetTempFileName();
        var exporter = new DataExporter();

        exporter.Export(_tempFile);

        Assert.IsNotEmpty(File.ReadAllText(_tempFile));
    }

    [TestCleanup]
    public void Cleanup()
    {
        if (_tempFile is not null && File.Exists(_tempFile))
        {
            File.Delete(_tempFile);
        }
    }
}
```

**Key points:**

| Scenario | Solution | Min Version |
|----------|----------|-------------|
| Windows-only | `[OSCondition(OperatingSystems.Windows)]` | MSTest 3.10 |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` | MSTest 3.10 |
| Flaky API | `[Retry(3)]` | MSTest 3.9 |
| Cleanup on failure | `[TestCleanup]` method | Any MSTest |

`[TestCleanup]` always runs after the test method—whether it passes, fails, or throws. This guarantees your temp files are deleted. You can also implement `IDisposable` on the test class as an alternative.
